        Case("__x_y~`_`a~~~\u000a***", listOf(Run("__x_y~", false, false, false, false), Run("_", false, false, false, true), Run("a~~~\u000a***", false, false, false, false))),
        Case("\u000a_**x_ya_", listOf(Run("\u000a", false, false, false, false), Run("**x_ya", false, true, false, false))),
    )
}
